3	export const runCli = (input: string): string =>
4	  JSON.stringify(runScenario(JSON.parse(input) as Scenario));
5	
6	const readStdin = async (): Promise<string> => {
7	  const chunks: string[] = [];
8	  process.stdin.setEncoding("utf8");
9	  for await (const chunk of process.stdin) chunks.push(chunk);
10	
11	  return chunks.join("");
12	};
13	
14	// Only when run as the executable — importing this module (as the spec does)
15	// must not consume stdin.
16	if (process.argv[1]?.endsWith("cli.ts") || process.argv[1]?.endsWith("cli.js")) {
17	  process.stdout.write(runCli(await readStdin()));
18	}
